-- Migration: generated_vibez_history
-- Stores every Vibez (GroupFlow) generated by a user so Pro users
-- can browse their full generation history from the Profile screen.

CREATE TABLE IF NOT EXISTS public."GeneratedVibez" (
    id              TEXT        PRIMARY KEY DEFAULT gen_random_uuid()::text,
    "userId"        TEXT        NOT NULL,
    "flowId"        TEXT        NOT NULL,
    "flowData"      JSONB       NOT NULL,
    "generatedAt"   TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    CONSTRAINT "GeneratedVibez_userId_flowId_key" UNIQUE ("userId", "flowId")
);

ALTER TABLE public."GeneratedVibez" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "generated_vibez_own"
    ON public."GeneratedVibez"
    FOR ALL
    USING (auth.uid()::text = "userId")
    WITH CHECK (auth.uid()::text = "userId");

CREATE POLICY "generated_vibez_service"
    ON public."GeneratedVibez"
    FOR ALL
    USING (auth.role() = 'service_role');

CREATE INDEX IF NOT EXISTS "GeneratedVibez_userId_generatedAt_idx"
    ON public."GeneratedVibez" ("userId", "generatedAt" DESC);
